def GS(i,fam,vt,va,steps=6):
    q=P(i); cs,n=ids(q); F=SEQ[fam]
    C={c:("조건",r"점화식의 조건.") for c in cs}; C[cs[0]]=("수열",r"첫째항의 범위."); C[cs[-1]]=("묻는 것",r"구하는 값.")
    titles=["원리","시작"]+["역추적"]*(n-4)+["예시","답"]
    S=[(t,[cs[0]] if k<n-1 else [cs[-1]]) for k,t in enumerate(titles)]
    I(q,F['w'],F['i'],C,[BK],S,[(h,cs[0],[p]) for h,p in F['T']],[("변형",[vt],va,r"앞으로 계산해 확인.")],F['l'])
def GC(i,fam,vt,va,vh):
    q=P(i); cs,n=ids(q); F=CF[fam]
    C={c:("조건",r"문항의 조건.") for c in cs}; C[cs[0]]=("설정",r"주어진 함수와 정의."); C[cs[-1]]=("묻는 것" if len(cs)>1 else "설정과 묻는 것",r"구하는 값.")
    assert len(F['S'])==n,(q,n)
    S=[(t,[cs[0]] if k<n-1 else [cs[-1]]) for k,t in enumerate(F['S'])]
    I(q,F['w'],F['i'],C,F['K'],S,[(h,cs[0],[p]) for h,p in F['T']],[("변형",[vt],va,vh)],F['l'])
